const repo = "acme/api";
const cutoff = Date.parse("2026-06-01T00:00:00Z");
const candidates: { number: number; title: string; updated_at: string }[] = [];
const seen = new Set<number>();

let page: number | null = 1;
let pages = 0;
while (page !== null && pages < 100) {
  const res = await tools.list_issues({ repo, state: "open", label: "bug", page });
  pages++;
