    const noMilestone = it.milestone === null || it.milestone === undefined;
    const updated = Date.parse(it.updated_at);
    if (hasBug && noMilestone && updated < cutoff) {
      candidates.push({ number: it.number, title: it.title, updated_at: it.updated_at });
    }
  }
  page = res.next_page;
}

const results: { number: number; labels?: string[]; error?: string }[] = [];
for (const c of candidates) {
  try {
    const r = await tools.add_label({ repo, number: c.number, label: "stale" });
    results.push({ number: c.number, labels: r.labels.map((l) => l.name) });
  } catch (e) {
    results.push({ number: c.number, error: String((e as Error).message) });
  }
}

console.log(JSON.stringify({ pages, scanned: seen.size, candidates, results }, null, 2));
return { pages, scanned: seen.size, labeled: results.filter((r) => !r.error).map((r) => r.number), failed: results.filter((r) => r.error) };
